const input = $input.first().json;
const job = input.job ?? input;
if (job.kind !== 'reconcile' || !job.id || !job.client_id || !job.target_id || !job.leaseToken) throw new Error('Contrato reconcile v1 invalido');
return [{ json: { schemaVersion: 1, job } }];

const job = $('Validar trabajo').first().json.job;
const context = $input.first().json;
const provider = job.payload?.providerState;
if (!provider) throw new Error('Conecta la consulta de Postiz y entrega payload.providerState');
const allowed = new Set(['scheduled', 'published', 'failed', 'cancelled', 'unknown']);
if (!allowed.has(provider.status)) throw new Error('Estado Postiz no reconocido');
if (provider.status === 'published' && (!provider.publishedAt || Number.isNaN(Date.parse(provider.publishedAt)))) throw new Error('published requiere publishedAt verificable');
if (provider.status === 'scheduled' && (!provider.confirmedScheduledAt || Number.isNaN(Date.parse(provider.confirmedScheduledAt)))) throw new Error('scheduled requiere confirmedScheduledAt');
const publication = { status: provider.status, confirmedScheduledAt: provider.confirmedScheduledAt ?? null, postizPostId: provider.postizPostId ? String(provider.postizPostId) : null, providerPostId: provider.providerPostId ? String(provider.providerPostId) : null, externalUrl: provider.externalUrl ?? null, publishedAt: provider.publishedAt ?? null, errorCode: provider.errorCode ?? null, errorMessage: provider.errorMessage ?? null };
const event = { schemaVersion: 1, clientId: job.client_id, entityType: 'publication', entityId: job.target_id, eventType: `postiz.${provider.status}`, sourceEventId: provider.eventId ?? `reconcile:${job.id}:${provider.status}`, occurredAt: provider.occurredAt ?? new Date().toISOString(), publicationStatus: provider.status, payload: { ...publication, workflowVersion: 1, accountCount: (context.accounts ?? []).length } };
return [{ json: { schemaVersion: 1, clientId: job.client_id, status: provider.status === 'unknown' ? 'unknown' : 'succeeded', publication, event, result: { workflowVersion: 1, reconciled: true }, leaseToken: job.leaseToken, jobId: job.id } }];
